const paddedMonth = String(month).padStart(2, "0");

// اولین روز ماه شمسی
const start = moment(`${year}-${paddedMonth}-01`, "jYYYY-jMM-jDD")
  .format("YYYY-MM-DD");

// تعداد روزهای ماه
let lastDay;

if (Number(month) <= 6) {
  lastDay = 31;
} else if (Number(month) <= 11) {
  lastDay = 30;
} else {
  lastDay = moment.jIsLeapYear(Number(year)) ? 30 : 29;
}

// آخرین روز ماه شمسی
const end = moment(
  `${year}-${paddedMonth}-${lastDay}`,
  "jYYYY-jMM-jDD"
).format("YYYY-MM-DD");

console.log("START:", start);
console.log("END:", end);
